// ─────────────────────────────────────────────────────────────────────────────
// SUB-COMPONENTS
// ─────────────────────────────────────────────────────────────────────────────

function StatusDot({ status }: { status: 'operational' | 'degraded' | 'down' | 'loading' }) {
  const color =
    status === "operational" ? "#10b981" :
    status === "loading"     ? "#3b82f6" :
    status === "degraded"    ? "#f59e0b" : "#ef4444";
  return (
    <span className="relative flex h-2.5 w-2.5 flex-shrink-0">
      <span className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-60"
        style={{ backgroundColor: color }} />
      <span className="relative inline-flex rounded-full h-2.5 w-2.5"
        style={{ backgroundColor: color }} />
    </span>
  );
}

function HealthSection({ id, data, expanded, onToggle, isDark, loading }: { id: string; data: HealthData; expanded: boolean; onToggle: (id: string) => void; isDark: boolean; loading?: boolean }) {
  const isOk      = data.status === "operational";
  const isDegraded = data.status === "degraded";
  const isLoading = data.status === "loading";
  const borderAccent = isOk ? "rgba(16,185,129,0.3)" : isDegraded ? "rgba(245,158,11,0.3)" : isLoading ? "rgba(59,130,246,0.3)" : "rgba(239,68,68,0.3)";
  const statusLabel  = isOk ? "Operational" :  isDegraded ? "Degraded" : isLoading ? "Loading..." : "Down";
  const statusColor  = isOk ? "text-emerald-400" : isDegraded ? "text-amber-400" : isLoading ? "text-blue-400" : "text-red-400";

  return (
    <div className="rounded-xl border overflow-hidden transition-all duration-300"
      style={{ borderColor: expanded ? borderAccent : isDark ? "rgba(100,116,139,0.2)" : "rgba(203,213,225,0.3)", background: isDark ? "rgba(15,23,42,0.6)" : "rgba(241,245,249,0.4)" }}>
      <button onClick={() => onToggle(id)}
        className={`w-full flex items-center gap-4 px-5 py-4 transition-colors text-left ${ isDark ? "hover:bg-white/[0.03]" : "hover:bg-black/[0.02]"}`}>
        <StatusDot status={data.status} />
        <span className={`flex-1 font-semibold tracking-wide text-sm ${ isDark ? "text-slate-100" : "text-slate-900"}`}>{data.label}</span>
        <span className={`text-xs font-medium ${statusColor} tabular-nums`}>{statusLabel}</span>
        <span className={`text-xs hidden sm:block tabular-nums ${ isDark ? "text-slate-500" : "text-slate-600"}`}>↑ {data.uptime}</span>
        <span className={`text-xs hidden sm:block tabular-nums ${ isDark ? "text-slate-500" : "text-slate-600"}`}>{data.responseTime}</span>
        <svg className={`w-4 h-4 flex-shrink-0 transition-transform duration-300 ${ isDark ? "text-slate-500" : "text-slate-600"}`}
          style={{ transform: expanded ? "rotate(180deg)" : "rotate(0deg)" }}
          fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
        </svg>
      </button>
      <div className="overflow-hidden transition-all duration-300"
        style={{ maxHeight: expanded ? "400px" : "0px", opacity: expanded ? 1 : 0 }}>
        <div className={`px-5 pb-5 pt-1 border-t ${ isDark ? "border-slate-700/40" : "border-slate-200/60"}`}>
          {loading ? (
            <div className="flex justify-center py-8">
              <LoadingSpinner loading={true} size="sm" />
            </div>
          ) : (
            <>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">
                {data.details.map((d: { label: string; value: string; ok: boolean }) => (
                  <div key={d.label} className="rounded-lg px-3 py-2.5"
                    style={{ background: isDark ? "rgba(30,41,59,0.7)" : "rgba(241,245,249,0.5)" }}>
                    <div className="flex items-center gap-1.5 mb-1">
                      <span className="w-1.5 h-1.5 rounded-full flex-shrink-0"
                        style={{ background: d.ok ? "#10b981" : "#ef4444" }} />
                      <span className={`text-[10px] uppercase tracking-wider font-medium ${ isDark ? "text-slate-400" : "text-slate-600"}`}>{d.label}</span>
                    </div>
                    <span className={`text-xs font-semibold ${ d.ok ? (isDark ? "text-slate-200" : "text-slate-900") : "text-red-400"}`}>{d.value}</span>
                  </div>
                ))}
              </div>
              <div className={`flex gap-4 text-[11px] ${ isDark ? "text-slate-500" : "text-slate-600"}`}>
                <span>Region: <span className={isDark ? "text-slate-400" : "text-slate-700"}>{data.region}</span></span>
                <span>Last deploy: <span className={isDark ? "text-slate-400" : "text-slate-700"}>{data.lastDeploy}</span></span>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function TunisiaMap({ regions, selectedRegion, onSelect }: { regions: Region[]; selectedRegion: string | null; onSelect: (id: string | null) => void }) {
  const maxUsers = Math.max(...regions.map((r: Region) => r.users));

  return (
    <div className="flex justify-center">
      {/* 
        Using the EXACT same viewBox as the original SVG: "0 0 283.5 538.6"
        The clip region in the original is x:11.1-269.1, y:43.3-493.3
        We crop to that with viewBox="11 43 258 450" to show only Tunisia
      */}
      <svg
        viewBox="11 43 258 450"
        style={{
          width: "100%",
          maxWidth: "195px",
          filter: "drop-shadow(0 0 20px rgba(20,184,166,0.2))",
          overflow: "visible",
        }}
      >
        <defs>
          <clipPath id="tuniClip2">
            <rect x="11" y="43" width="258" height="450" />
          </clipPath>
          {regions.map((r: Region) => (
            <radialGradient key={`rg2-${r.id}`} id={`rg2-${r.id}`}
              cx={r.x} cy={r.y} r={r.radius * 2.8}
              gradientUnits="userSpaceOnUse">
              <stop offset="0%"   stopColor={`rgba(20,184,166,${(0.5 + 0.45*(r.users/maxUsers)).toFixed(2)})`} />
              <stop offset="55%"  stopColor={`rgba(20,184,166,${(0.12*(r.users/maxUsers)).toFixed(2)})`} />
              <stop offset="100%" stopColor="rgba(20,184,166,0)" />
            </radialGradient>
          ))}
        </defs>

        {/* ── All governorate paths as the base map ── */}
        <g clipPath="url(#tuniClip2)">
          {GOVERNORATE_PATHS.map((gov) => (
            <path key={gov.id} d={gov.d}
              fill="#0d1e2e"
              stroke="rgba(20,184,166,0.35)"
              strokeWidth="0.6"
              strokeLinejoin="round"
            />
          ))}
        </g>

        {/* ── Heat blobs clipped inside the map ── */}
        <g clipPath="url(#tuniClip2)">
          {regions.map((r: Region) => (
            <circle key={`blob-${r.id}`}
              cx={r.x} cy={r.y}
              r={r.radius * (selectedRegion === r.id ? 3.5 : 2.5)}
              fill={`url(#rg2-${r.id})`}
              style={{ transition: "r 0.35s ease" }}
            />
          ))}
        </g>

        {/* ── City pins & labels (not clipped so labels never cut off) ── */}
        {regions.map((r: Region) => {
          const intensity = r.users / maxUsers;
          const sel = selectedRegion === r.id;
          return (
            <g key={r.id} onClick={() => onSelect(sel ? null : r.id)}
              style={{ cursor: "pointer" }}>
              {sel && (
                <circle cx={r.x} cy={r.y} r={5} fill="none"
                  stroke="rgba(94,234,212,0.6)" strokeWidth="1"
                  style={{ animation: "ping 1.4s cubic-bezier(0,0,0.2,1) infinite" }} />
              )}
              <circle cx={r.x} cy={r.y}
                r={sel ? 3 : intensity > 0.28 ? 2.5 : 1.8}
                fill={sel ? "#5eead4" : `rgba(20,184,166,${(0.55+0.45*intensity).toFixed(2)})`}
                stroke={sel ? "rgba(255,255,255,0.9)" : "rgba(255,255,255,0.4)"}
                strokeWidth={sel ? 0.8 : 0.5}
                style={{ transition: "r 0.2s ease" }}
              />
              {(intensity > 0.14 || sel) && (
                <text x={r.x} y={r.y - 4}
                  textAnchor="middle"
                  fill={sel ? "#a7f3d0" : "rgba(203,213,225,0.9)"}
                  fontSize={sel ? "5" : "4"}
                  fontFamily="'DM Mono', monospace"
                  fontWeight="600"
                  style={{ pointerEvents: "none" }}>
                  {r.name}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// MAIN DASHBOARD
// ─────────────────────────────────────────────────────────────────────────────
export default function ApplicationMonitoringPage() {
  const { isDark } = useTheme();
  const navigate = useNavigate();

  const [healthData, setHealthData] = useState<{ [key: string]: HealthData }>(getDefaultHealthData());
  const [loadingStates, setLoadingStates] = useState({ frontend: true, backend: true, database: true, visitors: true });
  const [visitorsData, setVisitorsData] = useState(getInitialVisitorBase());
  const [suspiciousActivity, setSuspiciousActivity] = useState<{ currentRxMb: number; currentTxMb: number } | null>(null);
  const [suspicious_loading, setSuspiciousLoading] = useState(true);
  const [expandedSection, setExpandedSection] = useState<string | null>(null);
  const [selectedRegion, setSelectedRegion] = useState<string | null>(null);

  useEffect(() => {
    document.title = "Dashboard | Monitoring";
    
    // Fetch Frontend Stats
    getFrontendStats()
      .then((frontendStats) => {
        setHealthData((prev) => {
          const updated = { ...prev };
          if (frontendStats) {
            updated.frontend = {
              ...updated.frontend,
              status: frontendStats.status === 'up' ? 'operational' : 'down',
              responseTime: `${frontendStats.latencyMs || 0}ms`,
              uptime: "--",
              lastDeploy: "--",
              details: [
                { label: "Response Code", value: String(frontendStats.statusCode), ok: frontendStats.statusCode === 200 },
                { label: "Latency", value: `${frontendStats.latencyMs || 0}ms`, ok: frontendStats.latencyMs < 100 },
                { label: "Status", value: frontendStats.status === 'up' ? 'Up' : 'Down', ok: frontendStats.status === 'up' }
              ],
            };
          }
          return updated;
        });
      })
      .catch((error) => console.error("Failed to fetch frontend stats:", error))
      .finally(() => setLoadingStates((prev) => ({ ...prev, frontend: false })));

    // Fetch Backend/System Stats
    getSystemStats()
      .then((systemStats) => {
        setHealthData((prev) => {
          const updated = { ...prev };
          if (systemStats) {
            const cpuOk = systemStats.cpu.usagePercent < 80;
            const memOk = systemStats.memory.usagePercent < 85;
            const diskOk = systemStats.disk.usedPercent < 90;
            const netOk = systemStats.network.speedMbps > 50;
            const TxRxTotalOk = systemStats.network.totalRxMb + systemStats.network.totalTxMb < 100;
            const overallOk = cpuOk && memOk && diskOk;
            updated.backend = {
              ...updated.backend,
              status: overallOk ? 'operational' : 'degraded',
              responseTime: `${systemStats.network.latencyMs || 0}ms`,
              uptime: "--",
              lastDeploy: "--",
              details: [
                { label: "CPU Usage", value: `${systemStats.cpu.usagePercent}%`, ok: cpuOk },
                { label: "Memory Usage", value: `${systemStats.memory.usagePercent}%`, ok: memOk },
                { label: "Disk Usage", value: `${systemStats.disk.usedPercent}%`, ok: diskOk },
                { label: "Memory Total", value: `${systemStats.memory.totalMb}GB`, ok: true },
                { label: "Disk Free", value: `${systemStats.disk.freeGb}GB`, ok: diskOk },
                { label: "Network Speed", value: `${systemStats.network.speedMbps}Mbps`, ok: netOk },
                { label: "Total MB received", value: `${systemStats.network.totalRxMb}MB`, ok: TxRxTotalOk },
                { label: "Total MB transmitted", value: `${systemStats.network.totalTxMb}MB`, ok: TxRxTotalOk },
              ],
            };
          }
          return updated;
        });
      })
      .catch((error) => console.error("Failed to fetch system stats:", error))
      .finally(() => setLoadingStates((prev) => ({ ...prev, backend: false })));

    // Fetch Database Stats
    getDBStats()
      .then((dbStats) => {
        setHealthData((prev) => {
          const updated = { ...prev };
          if (dbStats) {
            updated.database = {
              ...updated.database,
              status: dbStats.status === 'up' ? 'operational' : 'down',
              responseTime: `${dbStats.latencyMs}ms`,
              uptime: "--",
              lastDeploy: "--",
              details: [
                { label: "Status", value: dbStats.status === 'up' ? 'Up' : 'Down', ok: dbStats.status === 'up' },
                { label: "Latency", value: `${dbStats.latencyMs}ms`, ok: dbStats.latencyMs < 100 },
                { label: "Ping", value: dbStats.ping.ok === 1 ? "Connected" : "Disconnected", ok: dbStats.ping.ok === 1 },
              ],
            };
          }
          return updated;
        });
      })
      .catch((error) => console.error("Failed to fetch database stats:", error))
      .finally(() => setLoadingStates((prev) => ({ ...prev, database: false })));

    // Fetch Suspicious Activity Stats
    getSuspeciousActivityStats()
      .then((suspiciousStats) => {
        if (suspiciousStats && suspiciousStats.network) {
          setSuspiciousActivity({
            currentRxMb: suspiciousStats.network.currentRxMb,
            currentTxMb: suspiciousStats.network.currentTxMb,
          });
        }
      })
      .catch((error) => console.error("Failed to fetch suspicious activity stats:", error))
      .finally(() => setSuspiciousLoading(false));

    // Fetch Visitor Stats
    getVisitorStats()
      .then((visitorStats) => {
        setVisitorsData((prev) => {
          const regionMap = new Map<string, Region>();
          prev.regions.forEach((region) => {
            // Store regions by lowercase name for case-insensitive matching
            regionMap.set(region.name.toLowerCase(), region);
          });

          // Initialize regions with 0 users
          const updatedRegions = prev.regions.map(r => ({ ...r, users: 0 }));

          // Process IP list and match locations to regions
          if (visitorStats.ipsList && visitorStats.ipsList.length > 0) {
            visitorStats.ipsList.forEach((entry) => {
              if (entry.IPrecord.location) {
                const location = entry.IPrecord.location.toLowerCase();
                const matchedRegion = updatedRegions.find(r => location.includes(r.name.toLowerCase()));
                if (matchedRegion) {
                  matchedRegion.users += entry.users;
                }
              }
            });
          }

          // Filter regions with users > 0 and calculate total
          const activeRegions = updatedRegions.filter(r => r.users > 0);
          const totalVisitors = activeRegions.reduce((sum, r) => sum + r.users, 0);

          return {
            totalVisitors,
            activeToday: visitorStats.VisitorStats?.dailyVisitors || 0,
            newThisWeek: visitorStats.weeklyDailyVisitorsSum || 0,
            regions: activeRegions,
          };
        });
      })
      .catch((error) => console.error("Failed to fetch visitor stats:", error))
      .finally(() => setLoadingStates((prev) => ({ ...prev, visitors: false })));
  }, []);

  const toggle = (id: string) => setExpandedSection((p) => (p === id ? null : id));

  const overallOk    = Object.values(healthData).every((s) => s.status === "operational");
  const loadingAny   = Object.values(healthData).some((s) => s.status === "loading");
  const hasDegraded  = Object.values(healthData).some((s)  => s.status === "degraded");
  const overallStatus = overallOk ? "All Systems Operational" : loadingAny ? "Metrics are Loading..." : hasDegraded ? "Partial Degradation" : "System Outage";
  const overallColor  = overallOk ? "#10b981" : loadingAny ? "#3b82f6" : hasDegraded ? "#f59e0b" : "#ef4444";
  const activeRegion  = selectedRegion ? visitorsData.regions.find((r) => r.id === selectedRegion) : null;

  const lightBg = "linear-gradient(135deg, #f8fafc 0%, #f1f5f9 40%, #ecf5f4 70%, #f8fafc 100%)";
  const darkBg = "linear-gradient(135deg, #020817 0%, #0f172a 40%, #0d1f2d 70%, #020817 100%)";
  const bgGradient = isDark ? darkBg : lightBg;

  return (
    <div className={`min-h-screen py-10 px-4 pt-20 ${isDark ? "dark" : ""}`}
      style={{ background: bgGradient, fontFamily:"'DM Sans',sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Mono:wght@400;500;600&display=swap');
        * { box-sizing:border-box; }
        @keyframes ping   { 75%,100%{ transform:scale(2);opacity:0 } }
        @keyframes fadeUp { from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)} }
        .animate-ping { animation:ping 1.4s cubic-bezier(0,0,0.2,1) infinite; }
        .afu { animation:fadeUp 0.5s ease both; }
        .d1{animation-delay:.1s}.d2{animation-delay:.2s}.d3{animation-delay:.3s}
      `}</style>

      <div className="max-w-5xl mx-auto space-y-8">
           <button
            onClick={() => navigate('/dashboard')}
            className="inline-flex items-center gap-2 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white mt-10 mb-4 transition-colors"
           >
                <ArrowLeft className="w-5 h-5" />
                Back to Dashboard
           </button>
        {/* Header */}
        <div className="afu flex items-center justify-between flex-wrap gap-3">
 
          <div>
            <h1 className={`text-2xl sm:text-3xl font-bold ${isDark ? "text-white" : "text-slate-900"}`}>System Monitor</h1>
          </div>
          <div className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-semibold ${isDark ? "" : "bg-opacity-20"}`}
            style={{ background:`${overallColor}${isDark ? "18" : "20"}`, border:`1px solid ${overallColor}${isDark ? "55" : "40"}`, color:overallColor, fontFamily:"'DM Mono',monospace" }}>
            <span className="w-2 h-2 rounded-full animate-ping" style={{ background:overallColor }} />
            {overallStatus}
          </div>
        </div>

        {/* ── Application Health ── */}
        <div className={`rounded-2xl p-6 space-y-3 afu d1 ${isDark ? "" : "bg-white/50"}`}
          style={{ background: isDark ? "rgba(15,23,42,0.7)" : "rgba(255,255,255,0.5)", border: isDark ? "1px solid rgba(51,65,85,0.5)" : "1px solid rgba(203,213,225,0.3)", backdropFilter:"blur(12px)" }}>
          <div className="flex items-center gap-3 mb-5">
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 ${isDark ? "dark" : ""}`}
              style={{ background: isDark ? "rgba(20,184,166,0.15)" : "rgba(20,184,166,0.1)" }}>
              <svg className="w-4 h-4 text-teal-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <div>
              <h2 className={`text-base font-bold tracking-wide ${isDark ? "text-slate-100" : "text-slate-900"}`}>Application Health</h2>
              <p className={`text-xs ${isDark ? "text-slate-500" : "text-slate-600"}`}>Real-time service status overview</p>
            </div>
            <div className={`ml-auto flex gap-2 text-[11px] font-medium`} style={{ fontFamily:"'DM Mono',monospace" }}>
              <span className={`px-2 py-1 rounded-md ${isDark ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" : "bg-emerald-100 text-emerald-700 border border-emerald-300"}`}>
                {Object.values(healthData).filter(s=>s.status==="operational").length} OK
              </span>
              {hasDegraded && (
                <span className={`px-2 py-1 rounded-md ${isDark ? "bg-amber-500/10 text-amber-400 border border-amber-500/20" : "bg-amber-100 text-amber-700 border border-amber-300"}`}>
                  {Object.values(healthData).filter(s=>s.status==="degraded").length} Degraded
                </span>
              )}
            </div>
          </div>
          {Object.entries(healthData).map(([id, data]) => (
            <HealthSection key={id} id={id} data={data} expanded={expandedSection===id} onToggle={toggle} isDark={isDark} loading={loadingStates[id as keyof typeof loadingStates]} />
          ))}

          {/* Suspicious Activity Metrics */}
          <div className={`rounded-xl p-4 mt-4 border-l-4 ${isDark ? "border-l-orange-500 bg-orange-500/5" : "border-l-orange-500 bg-orange-50"}`}>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <svg className="w-4 h-4 text-orange-500" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
                <span className={`text-xs font-semibold tracking-wide ${isDark ? "text-orange-400" : "text-orange-700"}`}>Suspicious Activity Monitoring</span>
              </div>
              <span className={`text-xs px-2 py-1 rounded-md ${isDark ? "bg-orange-500/10 text-orange-400" : "bg-orange-100 text-orange-700"}`}>
                {suspicious_loading ? "Loading..." : "Monitoring"}
              </span>
            </div>
            
            {suspicious_loading ? (
              <div className="flex justify-center py-4">
                <LoadingSpinner loading={true} size="sm" />
              </div>
            ) : suspiciousActivity ? (
              <div className="grid grid-cols-2 gap-3">
                <div className={`rounded-lg p-3 ${isDark ? "bg-slate-700/30" : "bg-orange-100/30"}`}>
                  <div className={`text-xs ${isDark ? "text-slate-400" : "text-slate-600"}`}>Incoming Traffic</div>
                  <div className={`text-lg font-bold ${isDark ? "text-orange-400" : "text-orange-600"}`} style={{ fontFamily: "'DM Mono', monospace" }}>
                    {suspiciousActivity.currentRxMb.toFixed(2)} MB
                  </div>
                </div>
                <div className={`rounded-lg p-3 ${isDark ? "bg-slate-700/30" : "bg-orange-100/30"}`}>
                  <div className={`text-xs ${isDark ? "text-slate-400" : "text-slate-600"}`}>Outgoing Traffic</div>
                  <div className={`text-lg font-bold ${isDark ? "text-orange-400" : "text-orange-600"}`} style={{ fontFamily: "'DM Mono', monospace" }}>
                    {suspiciousActivity.currentTxMb.toFixed(2)} MB
                  </div>
                </div>
                {(suspiciousActivity.currentRxMb > 50 || suspiciousActivity.currentTxMb > 50) ? (
                  <div className={`col-span-2 rounded-lg p-3 ${isDark ? "bg-red-500/10" : "bg-red-100/30"}`}>
                    <div className={`text-xs ${isDark ? "text-red-400" : "text-red-600"}`}>Alert: Unusual traffic detected!</div>
                  </div>
                ) : (
                    <p className={`text-xs ${isDark ? "text-slate-500" : "text-slate-600"}`}>No suspicious activity detected</p>   
                )}
              </div>
            ) : (
              <div className={`text-xs ${isDark ? "text-slate-500" : "text-slate-600"}`}>No data available</div>
            )}
          </div>
        </div>

        {/* ── VisitorBase ── */}
        <div className={`rounded-2xl p-6 afu d2 ${isDark ? "" : "bg-white/50"}`}
          style={{ background: isDark ? "rgba(15,23,42,0.7)" : "rgba(255,255,255,0.5)", border: isDark ? "1px solid rgba(51,65,85,0.5)" : "1px solid rgba(203,213,225,0.3)", backdropFilter:"blur(12px)" }}>
          <div className="flex items-center gap-3 mb-6">
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 ${isDark ? "dark" : ""}`}
              style={{ background: isDark ? "rgba(20,184,166,0.15)" : "rgba(20,184,166,0.1)" }}>
              <svg className="w-4 h-4 text-teal-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round"
                  d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z" />
              </svg>
            </div>
            <div>
              <h2 className={`text-base font-bold tracking-wide ${isDark ? "text-slate-100" : "text-slate-900"}`}>VisitorBase Status</h2>
              <p className={`text-xs ${isDark ? "text-slate-500" : "text-slate-600"}`}>Geographic distribution across Tunisia</p>
            </div>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-3 gap-3 mb-6">
            {loadingStates.visitors ? (
              <div className="col-span-3 flex justify-center py-6">
                <LoadingSpinner loading={true} size="sm" />
              </div>
            ) : (
              [
                { label:"Total Visitors",   value:visitorsData.totalVisitors.toLocaleString(),  icon:"👥" },
                { label:"Today's Visitors",  value:visitorsData.activeToday.toLocaleString(), icon:"⚡" },
                { label:"This Week Visitors", value:`+${visitorsData.newThisWeek}`,            icon:"🚀" },
              ].map((s) => (
                <div key={s.label} className="rounded-xl px-4 py-3 text-center"
                  style={{ background: isDark ? "rgba(30,41,59,0.7)" : "rgba(228,228,231,0.4)", border: isDark ? "1px solid rgba(51,65,85,0.4)" : "1px solid rgba(203,213,225,0.3)" }}>
                  <div className="text-xl mb-1">{s.icon}</div>
                  <div className={`text-lg font-bold ${isDark ? "text-teal-300" : "text-teal-600"}`} style={{ fontFamily:"'DM Mono',monospace" }}>{s.value}</div>
                  <div className={`text-[10px] uppercase tracking-wider mt-0.5 ${isDark ? "text-slate-500" : "text-slate-600"}`}>{s.label}</div>
                </div>
              ))
            )}
          </div>

          {/* Map + sidebar */}
          {!loadingStates.visitors && (
          <div className="grid sm:grid-cols-2 gap-6 items-start">
            <TunisiaMap regions={visitorsData.regions} selectedRegion={selectedRegion} onSelect={setSelectedRegion} />

            <div className="space-y-2">
              {activeRegion ? (
                <div className="rounded-xl p-4 mb-3"
                  style={{ background: isDark ? "rgba(20,184,166,0.08)" : "rgba(20,184,166,0.05)", border: isDark ? "1px solid rgba(20,184,166,0.3)" : "1px solid rgba(20,184,166,0.2)" }}>
                  <div className="flex items-center justify-between mb-3">
                    <h3 className={`font-bold ${isDark ? "text-teal-300" : "text-teal-600"} text-sm`}>{activeRegion.name}</h3>
                    <button onClick={() => setSelectedRegion(null)} className={`${isDark ? "text-slate-500 hover:text-slate-300" : "text-slate-400 hover:text-slate-600"} text-xs`}>✕ close</button>
                  </div>
                  <div className="space-y-2">
                    {[
                      { label:"Users", value:activeRegion.users.toLocaleString() },
                      { label:"Share", value:`${visitorsData.totalVisitors > 0 ? ((activeRegion.users/visitorsData.totalVisitors)*100).toFixed(1) : 0}%` },
                    ].map((item) => (
                      <div key={item.label} className="flex justify-between text-xs">
                        <span className={isDark ? "text-slate-400" : "text-slate-600"}>{item.label}</span>
                        <span className={`${isDark ? "text-slate-200" : "text-slate-900"} font-semibold`} style={{ fontFamily:"'DM Mono',monospace" }}>{item.value}</span>
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                <p className={`${isDark ? "text-slate-500" : "text-slate-600"} text-xs mb-3 italic`}>Click a pin on the map to see region details.</p>
              )}

              <div className="space-y-1.5 max-h-64 overflow-y-auto pr-1"
                style={{ scrollbarWidth:"thin", scrollbarColor: isDark ? "#334155 transparent" : "#cbd5e1 transparent" }}>
                {visitorsData.regions.slice().sort((a: Region, b: Region) => b.users - a.users).map((r: Region) => {
                  const pct = visitorsData.totalVisitors > 0 ? (r.users/visitorsData.totalVisitors)*100 : 0;
                  const sel = selectedRegion===r.id;
                  return (
                    <button key={r.id} onClick={()=>setSelectedRegion(sel?null:r.id)}
                      className="w-full text-left rounded-lg px-3 py-2 transition-colors"
                      style={{ background: isDark ? (sel?"rgba(20,184,166,0.12)":"rgba(30,41,59,0.5)") : (sel?"rgba(20,184,166,0.08)":"rgba(20,184,166,0.03)"), border: isDark ? (sel?"1px solid rgba(20,184,166,0.35)":"1px solid rgba(51,65,85,0.3)") : (sel?"1px solid rgba(20,184,166,0.25)":"1px solid rgba(203,213,225,0.3)") }}>
                      <div className="flex items-center justify-between mb-1">
                        <span className={`text-xs font-semibold ${isDark ? "text-slate-300" : "text-slate-900"}`}>{r.name}</span>
                        <span className={`text-xs ${isDark ? "text-teal-400" : "text-teal-600"}`} style={{ fontFamily:"'DM Mono',monospace" }}>{r.users.toLocaleString()}</span>
                      </div>
                      <div className="w-full rounded-full h-1" style={{ background: isDark ? "rgba(51,65,85,0.6)" : "rgba(203,213,225,0.4)" }}>
                        <div className="h-1 rounded-full" style={{ width:`${pct}%`, background:"linear-gradient(90deg,#14b8a6,#0ea5e9)" }} />
                      </div>
                    </button>
                  );
                })}
              </div>

              <div className={`mt-3 pt-3 ${isDark ? "border-slate-700/40" : "border-slate-200/60"} flex items-center gap-4 text-[10px] ${isDark ? "text-slate-500" : "text-slate-600"}`}>
                <span className="flex items-center gap-1.5">
                  <span className="w-3 h-3 rounded-full" style={{ background:"rgba(20,184,166,0.85)" }} /> High density
                </span>
                <span className="flex items-center gap-1.5">
                  <span className="w-3 h-3 rounded-full" style={{ background:"rgba(20,184,166,0.25)" }} /> Low density
                </span>
              </div>
            </div>
          </div>
          )}
        </div>
      </div>
    </div>
  );
}